function clamp(value, min, max) {
  if (value < min) {
    return min
  }
  if (value > max) {
    return max
  }
  return value
}

// Coordinates and sizes are drawn rounded to one decimal.
function oneDecimal(value) {
  return Number(value.toFixed(1))
}

function onlyHex(value, fallback) {
  const text = String(value || '').trim()
  if (/^#[0-9a-fA-F]{6}$/.test(text)) {
    return text
  }
  return fallback
}

function hexToRgb(hex) {
  const value = hex.charAt(0) === '#' ? hex.substring(1) : hex
  return [
    parseInt(value.substring(0, 2), 16),
    parseInt(value.substring(2, 4), 16),
    parseInt(value.substring(4, 6), 16),
  ]
}

function rgbToHex(r, g, b) {
  function component(value) {
    const clamped = Math.round(clamp(value, 0, 255))
    const hex = clamped.toString(16)
    return hex.length === 1 ? '0' + hex : hex
  }

  return '#' + component(r) + component(g) + component(b)
}

function mix(a, b, amount) {
  const ca = hexToRgb(a)
  const cb = hexToRgb(b)
  return rgbToHex(
    ca[0] + (cb[0] - ca[0]) * amount,
    ca[1] + (cb[1] - ca[1]) * amount,
    ca[2] + (cb[2] - ca[2]) * amount,
  )
}

function dayOfWeek(year, month, day) {
  const offsets = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
  let y = year
  if (month < 3) {
    y -= 1
  }
  return (y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) + offsets[month - 1] + day) % 7
}

function themeColors(name, custom) {
  const themes = {
    'midnight-gallery': ['#132238', '#2A1E3F', '#F7F1E3', '#D8CBA8', '#D9A441'],
    'classic-black-on-white': ['#F8F8F2', '#EDEBE3', '#111111', '#333333', '#111111'],
    'classic-white-on-black': ['#080808', '#171717', '#FFFFFF', '#D7D7D7', '#FFFFFF'],
    'warm-paper': ['#F4E8CF', '#D8C7A3', '#2A2118', '#5B4630', '#B46A3C'],
    'sepia-press': ['#38291D', '#6A4A2C', '#F5E6C8', '#D8B882', '#C8873A'],
    'blueprint': ['#0A2540', '#173B63', '#EFF6FF', '#B9D7EA', '#73B7D6'],
    'forest-mist': ['#0F2A24', '#25483B', '#F0F3DD', '#C9D6B8', '#94B77B'],
    'terracotta': ['#321C19', '#6E3429', '#FFF1DE', '#E5B88B', '#D9825B'],
    'plum-night': ['#211529', '#4A2948', '#FFF3F7', '#D9B8D7', '#D88BA6'],
    'slate-gold': ['#19232D', '#35404A', '#F2EFE6', '#CFC6B2', '#D3A84C'],
    'red-gallery': ['#2D1115', '#5D1F28', '#FFF0E8', '#E4B9A7', '#C75B4A'],
    'green-room': ['#10271B', '#31533B', '#F5F2DD', '#D0D2A8', '#B6A94A'],
    'sandstone': ['#E9D8B8', '#BA9466', '#271E17', '#5A432B', '#9D6540'],
  }
  const chosen = name === 'custom' ? null : themes[name]
  if (!chosen) return custom
  return { backgroundStart: chosen[0], backgroundEnd: chosen[1], textColor: chosen[2], dateColor: chosen[3], accentColor: chosen[4] }
}

function asBool(value, fallback) {
  if (value === true || value === 'true' || value === '1') return true
  if (value === false || value === 'false' || value === '0') return false
  return fallback
}

function formatDate(raw, style) {
  if (style === 'none') {
    return ''
  }

  const parts = raw.split('-')
  if (parts.length < 3) {
    return raw
  }

  const year = Number(parts[0])
  const month = Number(parts[1])
  const day = Number(parts[2])
  const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
  const shortWeekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  const months = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ]
  const dow = dayOfWeek(year, month, day)

  if (style === 'iso') {
    return raw
  }
  if (style === 'short-weekday') {
    return shortWeekdays[dow] + ' ' + day + ' ' + months[month - 1].substring(0, 3)
  }
  return weekdays[dow] + ', ' + months[month - 1] + ' ' + day
}

function estimatedTextWidth(text, size) {
  let units = 0
  for (let i = 0; i < text.length; i++) {
    const ch = text.charAt(i)
    if (ch === ':' || ch === ' ') {
      units += 0.32
    } else if (ch === '1') {
      units += 0.48
    } else if (ch === ',' || ch === '.') {
      units += 0.25
    } else {
      units += 0.58
    }
  }
  return units * size
}

function fitFontSize(text, target, maxWidth) {
  const width = estimatedTextWidth(text, target)
  if (width <= maxWidth) {
    return target
  }
  return target * maxWidth / Math.max(width, 1)
}

function truncateToWidth(text, size, maxWidth) {
  if (estimatedTextWidth(text, size) <= maxWidth) {
    return text
  }

  let out = text
  while (out.length > 1 && estimatedTextWidth(out + '…', size) > maxWidth) {
    out = out.substring(0, out.length - 1)
  }
  return out + '…'
}

function timeLines(time) {
  const text = String(time || '')
  const spaceParts = text.split(' ')
  if (spaceParts.length >= 2) {
    const suffix = spaceParts.slice(1).join(' ').toUpperCase()
    return [spaceParts[0], suffix]
  }

  return [text]
}

// Path data for a rectangle with rounded corners.
function roundedRectPath(x, y, w, h, r) {
  const rr = clamp(r, 0, Math.min(w, h) / 2)
  const left = oneDecimal(x)
  const top = oneDecimal(y)
  const right = oneDecimal(x + w)
  const bottom = oneDecimal(y + h)
  return `M ${oneDecimal(x + rr)} ${top}` +
    ` L ${oneDecimal(x + w - rr)} ${top}` +
    ` Q ${right} ${top} ${right} ${oneDecimal(y + rr)}` +
    ` L ${right} ${oneDecimal(y + h - rr)}` +
    ` Q ${right} ${bottom} ${oneDecimal(x + w - rr)} ${bottom}` +
    ` L ${oneDecimal(x + rr)} ${bottom}` +
    ` Q ${left} ${bottom} ${left} ${oneDecimal(y + h - rr)}` +
    ` L ${left} ${oneDecimal(y + rr)}` +
    ` Q ${left} ${top} ${oneDecimal(x + rr)} ${top} Z`
}

// The dithered dot field and the sweeping line behind the numerals.
function BackgroundTexture({ W, H, style, start, end, accent }) {
  if (style === 'none') {
    return null
  }

  const dots = []
  const minSide = Math.min(W, H)
  const step = clamp(minSide / 20, 18, 56)
  const dotA = mix(start, accent, 0.30)
  const dotB = mix(end, '#ffffff', 0.16)
  const columns = Math.ceil(W / step) + 1
  const rows = Math.ceil(H / step) + 1

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < columns; x++) {
      const wobble = ((x * 37 + y * 19) % 23) / 23
      const px = x * step + (wobble - 0.5) * step * 0.35
      const py = y * step + (((x * 11 + y * 29) % 17) / 17 - 0.5) * step * 0.35
      const distance = Math.abs(px - W * 0.72) / W + Math.abs(py - H * 0.28) / H
      let radius = step * clamp(0.07 + (1 - distance) * 0.20 + wobble * 0.08, 0.04, 0.25)
      let color = (x + y) % 2 === 0 ? dotA : dotB

      if (style === 'soft-gallery') {
        radius *= 1.55
        color = mix(color, end, 0.24)
      }

      dots.push(<circle cx={oneDecimal(px)} cy={oneDecimal(py)} r={oneDecimal(radius)} fill={color} opacity="0.42" />)
    }
  }

  const lineColor = mix(start, accent, style === 'soft-gallery' ? 0.28 : 0.44)
  const lineWidth = clamp(minSide / 210, 1.1, 5)
  const sweep =
    `M ${oneDecimal(W * 0.08)} ${oneDecimal(H * 0.79)}` +
    ` C ${oneDecimal(W * 0.27)} ${oneDecimal(H * 0.61)} ` +
    `${oneDecimal(W * 0.50)} ${oneDecimal(H * 0.94)} ` +
    `${oneDecimal(W * 0.92)} ${oneDecimal(H * 0.69)}`

  return (
    <>
      {dots}
      <path d={sweep} fill="none" stroke={lineColor} strokeWidth={oneDecimal(lineWidth)} opacity="0.62" />
    </>
  )
}

export function get(app) {
  // The scene sets settings.renderScale to 1, so the app is told the panel's
  // own size even on a big panel: this clock's sizes and their pixel limits
  // are worked out for the panel's pixels, and the drawing maps onto it one
  // to one.
  const W = app.frame.width
  const H = app.frame.height
  const minSide = Math.min(W, H)
  const portrait = H > W * 1.08
  const margin = minSide * 0.055

  const time = String(app.config.time || '--:--')
  const dateStyle = String(app.config.dateStyle || 'weekday-month-day')
  const date = formatDate(String(app.config.dateRaw || ''), dateStyle)
  const subtitle = dateStyle === 'none' ? '' : String(app.config.subtitle || '')
  const customTheme = {
    textColor: onlyHex(app.config.textColor, '#F7F1E3'),
    dateColor: onlyHex(app.config.dateColor, '#D8CBA8'),
    accentColor: onlyHex(app.config.accentColor, '#D9A441'),
    backgroundStart: onlyHex(app.config.backgroundStart, '#132238'),
    backgroundEnd: onlyHex(app.config.backgroundEnd, '#2A1E3F'),
  }
  const colors = themeColors(String(app.config.theme || 'midnight-gallery'), customTheme)
  const textColor = colors.textColor
  const dateColor = colors.dateColor
  const accentColor = colors.accentColor
  const bgStart = colors.backgroundStart
  const bgEnd = colors.backgroundEnd
  const textureEnabled = asBool(app.config.decorativeElements, true)
  const ornamentalEnabled = asBool(app.config.ornamentalDetails, true)
  const dateBoxEnabled = asBool(app.config.dateBox, true)
  const bgStyle = textureEnabled ? String(app.config.backgroundStyle || 'poster-dither') : 'none'
  const gradientEnabled = asBool(app.config.backgroundGradient, true)
  const font = String(app.config.fontFamily || 'PTSans-Bold.ttf')

  const innerW = W - margin * 2
  const innerH = H - margin * 2
  const clockMaxWidth = innerW * (portrait ? 0.88 : 0.90)
  const ruleGap = minSide * 0.026
  const lines = timeLines(time)
  const dateSize = clamp(minSide * (portrait ? 0.056 : 0.060), 20, 78)
  const captionSize = subtitle ? clamp(minSide * 0.032, 12, 36) : 0
  const dateBlock = ruleGap * 2.55 + dateSize * 1.35 + captionSize * 1.35
  const lineGap = portrait ? minSide * 0.018 : 0
  const availableForTime = Math.max(minSide * 0.2, innerH - dateBlock - minSide * 0.038)
  let timeSize = (availableForTime - lineGap * Math.max(0, lines.length - 1)) / Math.max(lines.length * 0.98, 1)

  for (let i = 0; i < lines.length; i++) {
    timeSize = Math.min(timeSize, fitFontSize(lines[i], timeSize, clockMaxWidth))
  }
  timeSize = clamp(timeSize, minSide * 0.13, portrait ? minSide * 0.52 : minSide * 0.49)

  const hasDate = dateStyle !== 'none'
  const timeBlockH = timeSize * lines.length + lineGap * Math.max(0, lines.length - 1)
  const contentH = timeBlockH + (hasDate ? dateBlock : 0)
  const top = margin + Math.max(0, (innerH - contentH) / 2)
  const firstBaseline = top + timeSize * 0.82
  const lastBaseline = firstBaseline + (timeSize + lineGap) * (lines.length - 1)
  const timeBottom = lastBaseline + timeSize * 0.18
  const ruleW = clamp(innerW * 0.22, minSide * 0.18, innerW * 0.42)
  const ruleY = timeBottom + ruleGap
  const captionY = ruleY + ruleGap + captionSize
  const dateY = ruleY + ruleGap + (subtitle ? captionSize * 1.35 : 0) + dateSize
  const safeDateY = Math.min(dateY, H - margin - dateSize * 0.15)
  const dateText = truncateToWidth(date, dateSize, innerW * 0.88)
  const captionText = truncateToWidth(subtitle.toUpperCase(), captionSize || 1, innerW)

  const frameLine = mix(bgStart, accentColor, 0.36)
  const cardFill = mix(bgEnd, bgStart, 0.50)
  const cardStroke = mix(bgStart, accentColor, 0.46)
  const shadow = mix(bgEnd, '#000000', 0.35)
  const horizon = mix(bgEnd, accentColor, 0.20)
  const glowCx = portrait ? W * 0.50 : W * 0.48
  const glowCy = portrait ? H * 0.38 : H * 0.43
  const glowR = Math.max(W, H) * (portrait ? 0.70 : 0.58)
  const dateCardW = clamp(estimatedTextWidth(dateText, dateSize) + minSide * 0.18, innerW * 0.42, innerW * 0.94)
  const dateCardH = dateSize * 1.62 + (subtitle ? captionSize * 1.30 : 0)
  const dateCardX = (W - dateCardW) / 2
  const dateCardY = safeDateY - dateSize * 1.04 - (subtitle ? captionSize * 1.25 : 0)
  const cornerRadius = clamp(minSide * 0.024, 10, 28)
  const dateCardPath = roundedRectPath(dateCardX, dateCardY, dateCardW, dateCardH, cornerRadius * 0.82)

  const horizonPath =
    `M 0 ${oneDecimal(H * 0.74)}` +
    ` C ${oneDecimal(W * 0.22)} ${oneDecimal(H * 0.66)} ` +
    `${oneDecimal(W * 0.52)} ${oneDecimal(H * 0.83)} ` +
    `${W} ${oneDecimal(H * 0.70)}` +
    ` L ${W} ${H} L 0 ${H} Z`
  const accentBarPath =
    `M ${oneDecimal(margin)} ${oneDecimal(margin + minSide * 0.095)}` +
    ` L ${oneDecimal(margin)} ${oneDecimal(H - margin - minSide * 0.095)}`

  // Each line of the time is drawn twice: a soft offset shadow, then the numerals.
  const timeText = lines.map((line, i) => {
    const baseline = firstBaseline + (timeSize + lineGap) * i
    return (
      <>
        <text
          x={oneDecimal(W / 2 + minSide * 0.010)}
          y={oneDecimal(baseline + minSide * 0.014)}
          textAnchor="middle"
          dominantBaseline="alphabetic"
          fontFamily={font}
          fontSize={oneDecimal(timeSize)}
          fontWeight="700"
          fill={shadow}
          opacity="0.30"
        >
          {line}
        </text>
        <text
          x={oneDecimal(W / 2)}
          y={oneDecimal(baseline)}
          textAnchor="middle"
          dominantBaseline="alphabetic"
          fontFamily={font}
          fontSize={oneDecimal(timeSize)}
          fontWeight="700"
          fill={textColor}
        >
          {line}
        </text>
      </>
    )
  })

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
      <defs>
        <linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2={H}>
          <stop offset="0" stopColor={bgStart} />
          <stop offset="0.58" stopColor={mix(bgStart, bgEnd, 0.52)} />
          <stop offset="1" stopColor={bgEnd} />
        </linearGradient>
        <radialGradient id="timeGlow" gradientUnits="userSpaceOnUse" cx={oneDecimal(glowCx)} cy={oneDecimal(glowCy)} r={oneDecimal(glowR)}>
          <stop offset="0" stopColor={accentColor} stopOpacity="0.30" />
          <stop offset="0.48" stopColor={accentColor} stopOpacity="0.10" />
          <stop offset="1" stopColor={accentColor} stopOpacity="0" />
        </radialGradient>
        <radialGradient
          id="vignette"
          gradientUnits="userSpaceOnUse"
          cx={oneDecimal(W * 0.50)}
          cy={oneDecimal(H * 0.50)}
          r={oneDecimal(Math.max(W, H) * 0.72)}
        >
          <stop offset="0" stopColor="#000000" stopOpacity="0" />
          <stop offset="0.72" stopColor="#000000" stopOpacity="0.08" />
          <stop offset="1" stopColor="#000000" stopOpacity="0.34" />
        </radialGradient>
      </defs>
      <rect x="0" y="0" width={W} height={H} fill={gradientEnabled ? 'url(#bg)' : bgStart} />
      {gradientEnabled && <rect x="0" y="0" width={W} height={H} fill="url(#timeGlow)" />}
      {ornamentalEnabled && <path d={horizonPath} fill={horizon} opacity="0.20" />}
      <BackgroundTexture W={W} H={H} style={bgStyle} start={bgStart} end={bgEnd} accent={accentColor} />
      {ornamentalEnabled && (
        <>
          <path
            d={roundedRectPath(margin, margin, innerW, innerH, cornerRadius)}
            fill="none"
            stroke={frameLine}
            strokeWidth={oneDecimal(clamp(minSide / 260, 1, 5))}
            opacity="0.86"
          />
          <path d={accentBarPath} stroke={accentColor} strokeWidth={oneDecimal(clamp(minSide / 95, 4, 11))} opacity="0.78" />
        </>
      )}

      {timeText}

      {hasDate && dateBoxEnabled && (
        <>
          <line
            x1={oneDecimal((W - ruleW) / 2)}
            y1={oneDecimal(ruleY)}
            x2={oneDecimal((W + ruleW) / 2)}
            y2={oneDecimal(ruleY)}
            stroke={accentColor}
            strokeWidth={oneDecimal(clamp(minSide / 130, 2, 8))}
          />
          <path d={dateCardPath} fill={cardFill} opacity="0.66" />
          <path
            d={dateCardPath}
            fill="none"
            stroke={cardStroke}
            strokeWidth={oneDecimal(clamp(minSide / 420, 1, 3))}
            opacity="0.74"
          />
        </>
      )}

      {subtitle !== '' && hasDate && (
        <text
          x={oneDecimal(W / 2)}
          y={oneDecimal(captionY)}
          textAnchor="middle"
          dominantBaseline="alphabetic"
          fontFamily="PTSans-Bold.ttf"
          fontSize={oneDecimal(captionSize)}
          fontWeight="700"
          fill={accentColor}
        >
          {captionText}
        </text>
      )}

      {hasDate && (
        <text
          x={oneDecimal(W / 2)}
          y={oneDecimal(safeDateY)}
          textAnchor="middle"
          dominantBaseline="alphabetic"
          fontFamily="PTSans-Regular.ttf"
          fontSize={oneDecimal(dateSize)}
          fill={dateColor}
        >
          {dateText}
        </text>
      )}
      {gradientEnabled && <rect x="0" y="0" width={W} height={H} fill="url(#vignette)" />}
    </svg>
  )
}
